prologue:
static MOD_UNUSED int player_score(void) {
    return API->player != 0 ? API->player->GetScore(SELF) : 0;
}

static MOD_UNUSED int player_lives(void) {
    return API->player != 0 ? API->player->GetLives(SELF) : 0;
}

/* 0 is x, 1 is y, 2 is z */
static MOD_UNUSED float player_position(int axis) {
    AmodPlayer player;
    if (API->player == 0) return 0.0f;
    memset(&player, 0, sizeof player);
    player.structSize = sizeof player;
    if (API->player->Get(SELF, &player) == 0) return 0.0f;
    return (axis >= 0 && axis < 3) ? player.position[axis] : 0.0f;
}
